) AS (
  VALUES 
    (600::BIGINT, 'EL PEOR PROFE QUE HE TENIDO, NO MATRICULEN CON ÉL, SIEMPRE AGARRA A ALGUNOS ESTUDIANTES ENTRE OJOS, ES SUMAMENTE PREPOTENTE, REPUGNANTE CON TODOS, HACE COMENTARIOS SUPER INNECESARIOS'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-05-06T00:00:00+00:00'::TIMESTAMPTZ, '5d2bf4db9b996916546c2623aaf89854b577e8535c1696b1dfc5884917d1f272'::TEXT, ARRAY[99]::BIGINT[]),
    (600::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2026-04-23T00:00:00+00:00'::TIMESTAMPTZ, 'ea095aff1c81762658b4bd0cf3bb7e92c7d3b84debedc04b5c681c5c55c2fccd'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Es una persona machista y viejo verde Hace de todo menos dar la clase y pasarla criticando algo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-02-22T00:00:00+00:00'::TIMESTAMPTZ, 'b847a99c0d8c8867301664408f438b5f65f06e22a81c95b7b21b7938e372d7d0'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'No acepta ningun comentario ni critica aunque sea constructiva, en pocas palabras el nunca pierde, califica segun sus intereses, sin logica aplicando reglas que a su conveniencia cambia a su parecer, entregue un examen a tiempo y completo pero no lo califico por el formato entregado que no menciono'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, '3b8b47e0b2ec12d87079f91e3335a18aea6488ff6cac279bdcb6613ebe325a67'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Fácilmente el peor profe que he tenido en el TEC. Prepotente, narcicista, machista, sexista y un completo patán a la hora de recibir críticas. Ojalá esté leyendo esto, hágale un favor a la comunidad del TEC y jubílese.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e9dc5895ce42bacbbb6ff86c9db2ac722f2060e86a8036af703d36cf4178fb95'::TEXT, ARRAY[99]::BIGINT[]),
    (600::BIGINT, 'Buen profesor y uno mejora con él, pero en este curso se pone más pesado. El proyecto final se hace insufrible porque es demasiado largo y hace muchas exposiciones que ni el semestre es suficiente para abarcarlas todas. NO sube las notas cuando tiene que hacerlo y da pareza estar encima de él.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'f6278172a92c3e207f8d1bc730df927fbd38c4e6d746bc6157f0639833e71a0f'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Por favor no tomen ningún curso con este señor es un irrespetuoso prepotente narcisista, me hubiera gustado haber sabido esto antes, para los que aun están a tiempo de salvarse de los insultos y humillaciones de este señor, se cree intocable y se burla de las quejas que hay en su contra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-10T00:00:00+00:00'::TIMESTAMPTZ, 'db1e7cf3b32ad5b46ba2195a64f863873f629f1b4b2085110a368dc25742c1c8'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Es un profesor prepotente, todo lo que diga debe darle razón, el curso no es nada del otro mundo, con un buen equipo se pasa fácil. Eso si siempre dele la razón al profe o va buscar humillarlo y mejor ni le haga consultas que igual va humillarlo por todo lo que pueda.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'c423e472ac46171059e30fb121632efe47d621d4392db8e289756e815a7223be'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El mae le gusta siempre tener la razón, si usted le lleva la contraria lo va humillar, yo pensaría dos veces si llevar el curso con este profesor. Además, https://www.crhoy.com/nacionales/investigan-a-docente-del-tec-por-llamar-hembrita-lesbiana-a-estudiante/'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'f907bef3d92d8b1f40b58bf78014636ebbab013b35bc8c9880623257b845cd69'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El mae siempre quiere tener la razón, siempre busca humillar a los estudiantes, es un mal profesor no vale la pena aguantar insultos. No recomiendo matricular el curso con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, '749907320734cb15c329a0c4bc42d7b6ed0911db2c1dfbd436f852dd30fe3c65'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Si uno se distrae un segundo o no escuchó lo que dijo, se pone de intenso de que no repite las cosas. Quién te crees? Ni que estuvieras dando un curso importante. A una persona que trabaja le dijo: "Verano no es para trabajar, solo para mi curso". No profe, no me gustó su curso de mierda.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-01-29T00:00:00+00:00'::TIMESTAMPTZ, '15f1cc44941b2431188123939124e630e69bd03a9dc688d7b61021b9f65f07fd'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Es irrespetuoso y trata muy mal a los estudiantes. Se pasa sencillo pero no creo que valga la pena andar aguantando insultos'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-01-24T00:00:00+00:00'::TIMESTAMPTZ, '57a5bd314a932e06e93bd43ffe68094ec339d37a66a1ade1b3bb0d1294cebb5d'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Pésimo profesor, no respeta a los estudiantes, cree que siempre tiene la razón aunque así no fuera, no lo recomiendo para nada, deberia irse de la universidad.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, '98132d7407bbcc21e3e8666ac028f7d8bbd45b612111b6fd3d3d6e929e30bf9e'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El men se cree muy importante, quiere tener la razón siempre, así que el curso se complica porque hay que hacer lo que él quiere, dice que le consulten cualquier duda, pero cuando se le hace una consulta responde grosero. Si solo lleva este curso en verano se pasa fácil, Si no evítelo mejor pide muc'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-01-20T00:00:00+00:00'::TIMESTAMPTZ, '41260ffa5049220d8401e43995001a4c280573c67c0e7706d5db9a53b24f2a4e'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Profesor machista, le gusta humillar a los estudiantes, evítelo, siempre buscar la tener la razón.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-01-17T00:00:00+00:00'::TIMESTAMPTZ, '0a2cf351c0f97f5259341777316d7d5331694a063c795376d093261860e51245'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El profe es bastante estricto, le gusta que uno preste atención porque hace muchas preguntas sobre lo visto para ver si realmente aprendió, hace presentaciones todas las semanas y siempre toca con personas diferentes, es muy directo y habla como tiene que ser aunque mucha gente diga que es muy grose'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '545696c9f1aa434782d59a8d8ce8ca0aba64199cb43f3020cdde5b9d2ab98347'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'El profe sabe mucho y tiene amplia experiencia. Las clases son muchas presentaciones que hacen los estudiantes, es difícil mantenerse atento por eso. El curso se pasa fácil y se aprende si hace a conciencia. Es pura vida, pero bastante cerrado. También es muy estricto con la atención al curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, '1b9257cc99164f6d3dc0f2d962d1ffd654bf643e1d62402f5218ce44978dbc33'::TEXT, ARRAY[309]::BIGINT[]),
    (600::BIGINT, 'Si eres un hombre heterosexual promedio enhorabuena te va a ir muy bien, salvo que le caigas mal. Si eres Lgbt, en mi caso soy un gay, va a ser una pesadilla. Primer dia de clase y me dijo que mis uñas eran de mariquita (tenia las uñas color naranja) y en todo el semestre pasó tratandome mal.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'df6b3bf01f58baade3bf6356473f30189c5da439aebd38fa3b52c5685dd2517e'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-01-22T00:00:00+00:00'::TIMESTAMPTZ, '3ecf8bb0f2c5e2e627639aafb4694769a932043c83de5e7058f1923092aa254b'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Un excelente profe, me sorprenden los otros comentarios porque no hubo ningún comentario fuera de tono. Uno de veras aprende y brinda mucha ayuda si la pide. Full lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-01-12T00:00:00+00:00'::TIMESTAMPTZ, '13cb27da9bd114d58548317aa28aae8080444d4448ce471f9ebc24aa3da0aadf'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Machista, homofobico, cerrado como un bombillo, siempre tiene la razón, demasiado ambiguo con lo que pide por escrito contra lo que pide en la sesión, arrogan Es una verguenza que con sus escándalos haya quedado como coordinador de la carrera en una Sede eso habla peor del resto de docentes del TEC.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '7e0b6ae7b88986a9e9091d30a3d841b8769813e0b92ef38e835bd608fe9e34da'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Profesor machista, homofóbico y transfóbico que ignora a las mujeres y cree que solo él tiene la razón. No escucha a los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-10-04T00:00:00+00:00'::TIMESTAMPTZ, '0bb45e0bf901ea33a358ac13eb3d89ea9cb544d436ed0a87e8102ecbea96f077'::TEXT, ARRAY[309]::BIGINT[]),
    (600::BIGINT, 'Muy buen profe. Una clase relativamente sencilla si se es ordenado y cuemta con un buen grupo de trabajo. El proyecto final es grupal y acerca de una empresa por lo general. No perdona entregas tardías, solo con comprobante médico. Ejemplos muy apegados a la realidad laboral.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a810324bb6529d9fba1110886c923988343218e015be3a0307ea6e996cd04e48'::TEXT, ARRAY[99]::BIGINT[]),
    (600::BIGINT, 'El profe tiene bastante conocimiento sobre el tema. A veces saca sus temas controversiales. Explica bien y es bastante estricto con las reglas. Solo cumpla con lo que pide y no le lleve la contraria. Un buen grupo de trabajo ayuda bastante. Se pasa normal con él y se aprende bastante. Tareas fáciles'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '01b75bbc2fcfc2074bcc968b5f5279620ea8b35d90f365370790e006c8b228a0'::TEXT, ARRAY[3431]::BIGINT[]),
    (600::BIGINT, 'El profesor explica bien la materia y se interesa por que todos sus estudiantes entiendan. Aunque es muy estricto. Se recomienda formar un buen equipo de trabajo para que el curso sea más llevadero.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-01-27T00:00:00+00:00'::TIMESTAMPTZ, '6f8bbe92ccfdd2bb1d8cfd4f40a3909a040cde46a32a650bac02e9809cce22c1'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Lo lleve en verano. El profe es el típico señor, aveces puede ser odioso y las instrucciones no son tan claras. El curso es muy fácil y se pasa bien con un buen grupo de trabajo. El profe no es tan malo como dice los comentarios pero si tienen sus cosillas, la clave es caerle relativamente bien'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, '243a5fe20713cd0106e49eddf63eb9e89575163703cc7727db96cc63d4f13a4d'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El curso fue el peor desperdicio de tiempo de mi carrera, completamente innecesario. Y el profesor lo hace aún peor: aburrido, necio e irrelevante.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2023-01-10T00:00:00+00:00'::TIMESTAMPTZ, '278696ad05c6a515ff47299bf40ec8a4b8a1c65f805e4c14ec130605a4c6df61'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Un excelente profesor la materia queda clara y pone ejemplos que se aplican a la vida real, el trabajo final se hace en una empresa. Usted no va a pasar con la ley del minimo esfuerzo ya que se requiere compromiso (lo normal a nivel de U) y eso es lo que a algunas personas les molesta del profe..'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'bd37e6e7199dd80f6234c547fe3d83794293b1e012351d6a66de001022e2239c'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Arrogante, cree que solo él tiene la razón. Y no entiende que las personas muchas veces tienen inconvenientes personales.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'd1bddc6ac39b2e244985fab651601edd5742b8e8823199f10b2328d3076355cb'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Curso fácil, pero no se aprende NADA. Como profesor.. arrogante, machista, presumido, fanfarrón, le gusta humillar estudiantes, ignora, etc.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '7026dcee12f24a58f76bd1683174b38c3fae0c951d84800d97d9c7e570596ea9'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'NUNCA lleven clase con ese profesor. El curso es facil, pero el profe casi nunca responde dudas, mas bien lo humilla a uno si pregunta algo. Es un arrogante homofobico que le importa mas degradar a los estudiantes por cosas que no tienen nada que ver con el curso, que dar la clase.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-02-02T00:00:00+00:00'::TIMESTAMPTZ, '938415e657e42a5d41c8d6aa6f096f85f2a6cc658ce988f8af089220f2cd6b23'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Pésimo profesor, le encanta humillar a los estudiantes frente a todos los demás y es el más arrogante.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'c66fd057981c1c548f79d9261e90b4c9d191adb52ddbbf2d2007c2f789326caf'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Sinceramente es uno de los peores que me ha tocado en el TEC, exige cámara y hace quedar a los estudiantes si no van a una exposición y exige cámara, llevar el curso en un semestre común va a ser un infierno.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, '203c6e196beb28cf49d9a9c4605233ab55077581b8dc692efcd06bb9836aa7b6'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Es bueno que lean la noticia y vean el video antes de matricular con él https://www.crhoy.com/nacionales/investigan-a-docente-del-tec-por-llamar-hembrita-lesbiana-a-estudiante/, un profesor engreído que se contradice solo, ofrece la oportunidad de preguntar pero al preguntarle regaña a todos'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'd6faa4328382356cf2f5d82c58d928d679997701029cc926dfbef73f68ed0757'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Excelente forma de organizar las clases, el mejor profesor de la licenciatura .'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'a23ed272adcf919a7780b137b62460b57b78a0693349f56efd003300aa90b28a'::TEXT, ARRAY[309]::BIGINT[]),
    (600::BIGINT, 'El más arrogante y acosador de todos. Pobres estudiantes bonitas'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-01-06T00:00:00+00:00'::TIMESTAMPTZ, 'bf8520a5b8432045df9e6c07ff8ccebe2651ee435a15b52c2b7804c94d422396'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'Pésimo profesor. No respeta pronombres y juzga a cada rato. No matricule con él. Hay caminos peores que la muerte.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-01-04T00:00:00+00:00'::TIMESTAMPTZ, '75a1680911778da0d762db05481fb7560ade0ebbaa37602b5566c7cc9f74c694'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El profe califica bastante duro y espera mucho de los estudiantes. Sin embargo, si usted participa, hace las evaluaciones y asiste siempre a clases de fijo pasa. El profe pide excelencia de los estudiantes y si alguien es vago o no quiere hacer las cosas le disgusta.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, '230020633d1d3544dd16d3fb19729c568acb4f906bb34080334f6cdc69662eba'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'El peor profesor que he tenido en la escuela. Siempre humilla a los estudiantes, arrogante a más no poder y se cree un súper profesor cuando en realidad es pésimo. De verdad nunca matriculen con él'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-19T00:00:00+00:00'::TIMESTAMPTZ, '55d456309ef0280569b72d977fc1a77ad08ec48ca8fc3898b0ec708b2f2bf44d'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Busquen la noticia de "Investigan a docente del tec por llamar hembrita lesbiana a estudiante". ES ESTE PROFESOR. Busquen el video completo en ESTUDIANTES TEC, donde se escucha que además parece andar de novio con una de las alumnas del grupo. ESO es él. Machista, jugando de peligroso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'f1e280542c4723d2e779642e3e48b1b5db89f9de43b90546f9a326a9d2b8969d'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'El curso no es dificil, de hecho lo considero muy facil, el problema es el profesor, las clases se vuelven muy aburridas si no a usted no le interesa, pero si le interesa las clases son buenas, lo mejor con el es conseguirse un BUEN equipo de trabajo por que si uno falta para exponer es menos nota'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '9faa83fa4be56f528f54464ad4b652c3fba35fcb215c81102de3c93bf24ae094'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El curso es regalado, llévelo sin miedo'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'be044c9ead5b0bbc05ffbb34b6cea6b5d227fd9849ec3b9c323dea711d54453a'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Buen profe. Califica justo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, '0a56da31f8ac360a6cfe7f5c0111fcdd9c886573a93c7265debb83f282d3c4a2'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'Sin lugar a dudas es el peor profesor que he tenido en la carrera, no debería de dar clases, no respeta las opiniones de los compañeros y tampoco deja instrucciones claras. Toda calificación es subjetiva, NUNCA matriculen con él.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '3dfcfe9c80455e5e3436bf2cf1c95f46b87f2992edde4e17499e577050f3ad60'::TEXT, ARRAY[965]::BIGINT[]),
    (600::BIGINT, 'El es súper arrogante, y se cree el súper profe, le encanta estar de batiendo de tema como la homosexualidad, aborto, etc. Deja muchos casos y tareas, pero son fáciles. La participación cuenta mucho, pero en realidad el califica como le da la gana, pero se pasa bien, con una súper nota'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '9d12db70118375afd6a032a8f04328cb0c2c2b357eef7bdb6b3a0cdf277d39a3'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Saca las presentaciones de internet, pone muchisimos casos que no sriven de nada. Siempre quiere debatir sobre aborto y cosas fuera de la clase. No aprendi nada con el. El curso se gana facil.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'adf714f1e3876b354342d5cb008192d2bcaca372b0c1c183c802abbda8ac65f0'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Es muy arrogante, cree que solo el tiene la razón. Cree que es profesor de escuela ya que regaña y habla por todo. Las clases prácticamente las dan los estudiantes ya que son exposiciones todos los días. La calificación es muy subjetiva, de acuerdo a criterio de él. Es homofobo y machista'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '0b455fa9cb3b36927020740eebde1c521d980b16af0bb649ba5147e7500ff0ec'::TEXT, ARRAY[3431]::BIGINT[]),
    (600::BIGINT, 'El profesor es súper arrogante, una vez dijo que los que creían en el aborto eran tontos, tema que ni siquiera tiene que ver con el curso.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-28T00:00:00+00:00'::TIMESTAMPTZ, '10e4d7a69a23b211c1352a3f1c91fbd83ae6ce41132d57d0c84eb1dc6cff1392'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Un completo dolor llevar clases con él. Se dedica a estar regañando. Los comentarios que hace en clase son fuera de tono e incluye demasiado su opinión personal irrelevante al tema en discusión. La calificación es sumamente subjetiva, baja y da puntos a su gusto, se pasa por alto las reglas del tec'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, '0f667496cd5de56cee2e1f746f94a05b55b87fa668fda1750a5a3e9d46501e98'::TEXT, ARRAY[2412]::BIGINT[]),
    (600::BIGINT, 'El profesor explica claro, usa diapositivas, es estricto con la asistencia por lo que es mejor no faltar NUNCA, no se puede usar el celular, ni hablar en la clase, los exámenes no son tan difíciles y no es tan estricto con el trab esc, eso sí,hay que exponer el proyecto, crear el producto y venderlo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-26T00:00:00+00:00'::TIMESTAMPTZ, '22b14f08cd5b79fd3a60e3e530edef27ab449260bce6d6a7fa93743c57128489'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2019-01-01T00:00:00+00:00'::TIMESTAMPTZ, 'f171881189affb1d145af507ba579fb8e095fdfa9de1161eb7ba86d16cb5d361'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Pésimo profesor, arrogante, pedante y poco preocupado por el respeto hacia ciertas minorías. Cambia el porcentaje para tener la oportunidad de bajar puntos a diestra y siniestra ya que baja puntos por la participación pero nunca apunta quien participa. Si cuestionas algo ya vas mal en el curso'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9d6d36ca3acdb50e4d24b307571b38f7bda0f9a7979a9cc35c113beb42ed644b'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'NO puedes salir al baño NUNCA. NO puedes usar el cel NUNCA.No puedes faltar a clases o pierdes varios % de la NOTA FINAL.La participación la asigna al final de semestre 100% subjetivo, a OJO. Puede ser muy pedante y grosero si no le caes tan bien.CURSO: fácil, no tarea, examen medio, proyecto medio.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-01-22T00:00:00+00:00'::TIMESTAMPTZ, '632f35f148cb54b8f1531b6c69cc1517d21276ce5a99bee36c8e656e743abb09'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Viejo Verde, narcisista, pedante y rajón. El curso lo pasa si le cae bien al mae'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-03T00:00:00+00:00'::TIMESTAMPTZ, '090456f9e65bf49be4ba2ab850ccad090419f815abfef8449cc8022a17a24460'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Las lecciones son aburridas, es un poco pedante y egocéntrico (lo que él dice y punto), los exámenes son fáciles y no es tan exigente con el proyecto.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '43043f081521ec2fac5f8548c6a07f756f47e2a666c551779276af61acc562ed'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Un profesor muy egocentrico. Se cree la máxima autoridad de todo, no le importa si usted tiene una justificación que venga de una autoridad mayor a él. Tiene sus preferencias aunque diga que no, si uno no es parte de ellas va a ser duro el semestre.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-04-14T00:00:00+00:00'::TIMESTAMPTZ, '45bb9a4ff1e26bea3d93f43453bea1e723118cdf4d65042b872fe18f196ca53e'::TEXT, ARRAY[1784]::BIGINT[]),
    (600::BIGINT, 'Puras presentaciones de los libros, no prepara la materia, y repite lo que ve. Sumamente retrógrado con sus reglas, no se puede ir al baño, cuadrado.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2017-04-06T00:00:00+00:00'::TIMESTAMPTZ, '006e68d2328e6ce257b6ae501fd874fe3c5e58fda22c7a624ab72d2bf98712a3'::TEXT, ARRAY[1883]::BIGINT[]),
    (600::BIGINT, 'Excelente profesor, no se guíen por lo que dicen los otros comentarios, es un profesor con mucha experiencia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e684e459db2bc8958c99e820476d948145d39928b94b3ca0eefe2e797bad8746'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Cambia los porcentajes de evaluación para tener mas ¨poder¨ a la hora de calificar al incluir un porcentaje Xs de participación pero nunca apunta quien participa y al final del semestre pone ese porcentaje a como el quiere.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-13T00:00:00+00:00'::TIMESTAMPTZ, '940309bbaba90853a98cb5312f0a840741a741c7ea08df4d9c4fb0664a45e2c2'::TEXT, ARRAY[1973, 1784]::BIGINT[]),
    (600::BIGINT, 'Las clases son puras presentaciones y la materia no queda clara.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, '425f0a4153e7b8cdc3c0f744ed179f0f6558efcec1d7b2f1ce227153868a2bab'::TEXT, ARRAY[1784]::BIGINT[]),
    (600::BIGINT, 'Explica bien, aunque es muy irresponsable algunas veces. Basa sus clases en presentaciones.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'a5b99d4a374d1d828906e8ce883838b70a2d95e6ccb68aae20d91318d7bcd4a6'::TEXT, ARRAY[1973, 1784]::BIGINT[]),
    (600::BIGINT, 'Comentarios fuera de lugar, reglas muy rígidas en clase. Autoritario y poco interesado en el aprendizaje de los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'd51dab9ad4fe5f88581b26c8ad4bb9571bfc8c70783ef69967780bbc6876d355'::TEXT, ARRAY[1784]::BIGINT[]),
    (600::BIGINT, 'Basa el curso en diapositivas, lo cual hace que el curso sea simple, pero, la materia no queda clara.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-13T00:00:00+00:00'::TIMESTAMPTZ, '0b3db612d854f5b68ded3b2fbea2e2f8052d0cd7a46c160fb9c80f64bbdb1b06'::TEXT, ARRAY[2469, 309]::BIGINT[]),
    (600::BIGINT, 'Tiene muchos estereotipos y hace comentarios/ejemplos fuera de lugar, relacionado a los estereotipos, durante las lecciones.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '06550ce14f2c3d5a59fca43b9ffd39676f1151a9267ac26aa1910af8f635e1f7'::TEXT, ARRAY[2453]::BIGINT[]),
    (600::BIGINT, 'Muy buen profesor. Clases son dinámicas porque estimula la participación. Se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'b6f21b2127897f595b2d85b715d959cb84f38f10201349b0a71f2204a4b3a798'::TEXT, ARRAY[2453]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
